16	var reverseProxyMetrics = struct {
17		once             sync.Once
18		upstreamsHealthy *prometheus.GaugeVec
19		logger           *zap.Logger
20	}{}
21	
22	func initReverseProxyMetrics(handler *Handler, registry *prometheus.Registry) {
23		const ns, sub = "caddy", "reverse_proxy"
24	
25		upstreamsLabels := []string{"upstream"}
26		reverseProxyMetrics.once.Do(func() {
27			reverseProxyMetrics.upstreamsHealthy = prometheus.NewGaugeVec(prometheus.GaugeOpts{
28				Namespace: ns,
29				Subsystem: sub,
30				Name:      "upstreams_healthy",
31				Help:      "Health status of reverse proxy upstreams.",
32			}, upstreamsLabels)
33		})
34	
35		// duplicate registration could happen if multiple sites with reverse proxy are configured; so ignore the error because
36		// there's no good way to capture having multiple sites with reverse proxy. If this happens, the metrics will be
37		// registered twice, but the second registration will be ignored.
38		if err := registry.Register(reverseProxyMetrics.upstreamsHealthy); err != nil &&
39			!errors.Is(err, prometheus.AlreadyRegisteredError{
40				ExistingCollector: reverseProxyMetrics.upstreamsHealthy,
41				NewCollector:      reverseProxyMetrics.upstreamsHealthy,
42			}) {
43			panic(err)
44		}
45	
46		reverseProxyMetrics.logger = handler.logger.Named("reverse_proxy.metrics")
47	}
48	
49	type metricsUpstreamsHealthyUpdater struct {
50		handler *Handler
51	}
52	
53	func newMetricsUpstreamsHealthyUpdater(handler *Handler, ctx caddy.Context) *metricsUpstreamsHealthyUpdater {
54		initReverseProxyMetrics(handler, ctx.GetMetricsRegistry())
55		reverseProxyMetrics.upstreamsHealthy.Reset()
56	
57		return &metricsUpstreamsHealthyUpdater{handler}
58	}
59	
60	func (m *metricsUpstreamsHealthyUpdater) init() {
61		go func() {
62			defer func() {
63				if err := recover(); err != nil {
64					if c := reverseProxyMetrics.logger.Check(zapcore.ErrorLevel, "upstreams healthy metrics updater panicked"); c != nil {
65						c.Write(
66							zap.Any("error", err),
67							zap.ByteString("stack", debug.Stack()),
68						)
69					}
70				}
71			}()
72	
73			m.update()
74	
75			ticker := time.NewTicker(10 * time.Second)
76			for {
77				select {
78				case <-ticker.C:
79					m.update()
80				case <-m.handler.ctx.Done():
81					ticker.Stop()
82					return
83				}
84			}
85		}()
86	}
87	
88	func (m *metricsUpstreamsHealthyUpdater) update() {
89		for _, upstream := range m.handler.Upstreams {
90			labels := prometheus.Labels{"upstream": upstream.Dial}
91	
92			gaugeValue := 0.0
93			if upstream.Healthy() {
94				gaugeValue = 1.0
95			}
96	
97			reverseProxyMetrics.upstreamsHealthy.With(labels).Set(gaugeValue)
98		}
99	}
