	// see the write error. deferred because flushing before the error routes
	// run would commit a 200 and lose the error status. it sits after the
	// access log defer so it still runs first.
	defer func() {
		if s.WriteTimeout <= 0 ||
			r.ProtoMajor != 1 ||
