1185	// shouldLogRequest returns true if this request should be logged.
1186	func (s *Server) shouldLogRequest(r *http.Request) bool {
1187		if s.accessLogger == nil || s.Logs == nil {
1188			// logging is disabled
1189			return false
1190		}
1191	
1192		// strip off the port if any, logger names are host only
1193		hostWithoutPort, _, err := net.SplitHostPort(r.Host)
1194		if err != nil {
1195			hostWithoutPort = r.Host
1196		}
1197	
1198		for loggerName := range s.Logs.LoggerNames {
1199			if certmagic.MatchWildcard(hostWithoutPort, loggerName) {
1200				// this host is mapped to a particular logger name
1201				return true
1202			}
1203		}
1204		for _, dh := range s.Logs.SkipHosts {
1205			// logging for this particular host is disabled
1206			if certmagic.MatchWildcard(hostWithoutPort, dh) {
1207				return false
1208			}
1209		}
1210		// if configured, this host is not mapped and thus must not be logged
1211		return !s.Logs.SkipUnmappedHosts
1212	}
